<?php $page_title='Pesanan Saya';include 'partials/header.php';require_login();$uid=$_SESSION['user']['id'];$st=$conn->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$st->bind_param('i',$uid);$st->execute();$orders=$st->get_result();?><section class="section container"><div class="section-head"><div><span class="muted">Transaksi</span><h2>Riwayat Pesanan</h2></div></div><?php if(isset($_GET['success'])):?><div class="alert success">Pesanan berhasil dibuat.</div><?php endif;?><div class="panel table-wrap"><table class="table"><tr><th>ID</th><th>Tanggal</th><th>Total</th><th>Pembayaran</th><th>Status</th></tr><?php while($o=$orders->fetch_assoc()):?><tr><td>#<?=$o['id']?></td><td><?=$o['created_at']?></td><td><?=rupiah($o['grand_total'])?></td><td><?=htmlspecialchars($o['payment_method'])?></td><td><span class="status"><?=$o['status']?></span></td></tr><?php endwhile;?></table></div></section><?php include 'partials/footer.php';?>
